SELECT COUNT(*) FROM badges as b, postHistory as ph, posts as p, users as u WHERE p.OwnerUserId = u.Id AND b.UserId = u.Id AND ph.UserId = u.Id AND p.AnswerCount>=0 AND p.FavoriteCount>=0 AND p.CreationDate<=CAST('2014-09-03 03:32:35' AS TIMESTAMP) AND u.CreationDate<=CAST('2014-09-12 22:21:49' AS TIMESTAMP)
